      W + " .zcc-wl-input{border-radius:8px !important;border:1.5px solid #dde3ec !important;padding:11px 14px !important;width:100% !important;display:block !important;margin-bottom:8px !important;outline:none !important;font-size:13.5px !important;transition:border-color 0.2s,box-shadow 0.2s !important;background:#fff !important;color:" + cfg.textColor + " !important;line-height:1.4 !important}" +
      W + " .zcc-wl-input::placeholder{color:#9ca3af !important}" +
      W + " .zcc-wl-btn{border-radius:" + btnRadius + " !important;background:" + cfg.primaryColor + " !important;color:#fff !important;padding:11px 20px !important;width:100% !important;font-weight:600 !important;border:none !important;cursor:pointer !important;font-size:13.5px !important;transition:filter 0.2s,box-shadow 0.2s,transform 0.2s !important;letter-spacing:0.01em !important;box-shadow:0 2px 8px " + cfg.primaryColor + "25 !important;display:flex !important;align-items:center !important;justify-content:center !important;gap:6px !important;margin-top:4px !important}" +
      W + " .zcc-wl-btn:hover{filter:brightness(1.06) !important;box-shadow:0 4px 14px " + cfg.primaryColor + "40 !important;transform:translateY(-1px) !important}" +
      W + " .zcc-wl-btn:active{filter:brightness(0.95) !important;transform:translateY(0) !important}" +
      buildSharedCss(W, cfg)
    );
  }

  // ── Inject CSS ────────────────────────────────────────────────────────────────
  function injectCss(wid, cfg, rad) {
    var css = buildWidgetCss(wid, cfg, rad);
    css += scopeCustomCss(cfg.customCss, wid);
    var styleEl = document.createElement("style");
    styleEl.textContent = css;
    document.head.appendChild(styleEl);
  }

  // ── SVG icon library — all icons are outlined/stroke style, 24×24 viewBox ──
  var ICONS = {
    location: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>',
