    xCircle:  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="m15 9-6 6"/><path d="m9 9 6 6"/></svg>',
    truck:    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="3" width="15" height="13" rx="1"/><path d="M16 8h4l3 3v5h-7V8z"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>',
    calendar: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>',
    clock:    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',
    card:     '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="4" width="22" height="16" rx="2"/><line x1="1" y1="10" x2="23" y2="10"/></svg>',
    refresh:  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>',
    mail:     '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>',
    users:    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
    spinner:  '<span class="zcc-spinner" aria-hidden="true"></span>',
    checkmark:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>'
  };

  // ── Shared: build widget inner HTML + wire up events ────────────────────────
  // showHeading: pass false when the caller already renders a heading (e.g. popup modal header)
  function buildWidgetInner(wid, cfg, btnLabel, showHeading) {
    var headingHtml = (showHeading !== false) ? (
      '<div class="zcc-heading">' +
        '<span class="zcc-heading-icon">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="' + escAttr(cfg.primaryColor) + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
        '</span>' +
        '<span>' + esc(cfg.heading) + '</span>' +
      '</div>'
    ) : '';
    return (
      headingHtml +
      '<div class="zcc-search-bar">' +
        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' +
          '<span class="zcc-btn-icon">' + ICONS.search + '</span>' +
          '<span class="zcc-btn-label">' + esc(btnLabel) + '</span>' +
        "</button>" +
      "</div>" +
      '<div id="' + wid + '-res" aria-live="polite"></div>'
    );
  }

  function wireWidget(wid, cfg, API_BASE, SHOP) {
    var inp = document.getElementById(wid + "-inp");
    var btn = document.getElementById(wid + "-btn");
    var res = document.getElementById(wid + "-res");
    if (!inp || !btn || !res) return;

    function normalizeZip(raw) {
      var z = raw.trim().toUpperCase();
      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
      return z;
    }

    // Store the original button HTML so we can restore it exactly after loading
    var btnOriginalHtml = btn.innerHTML;

    function setBtnLoading(loading) {
      btn.disabled = loading;
      if (loading) {
        btn.classList.add('zcc-btn--loading');
        // Replace entire button content with a lone spinner — no text overlap
        btn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
      } else {
        btn.classList.remove('zcc-btn--loading');
        // Restore original icon + label markup
        btn.innerHTML = btnOriginalHtml;
        // Keep button text in sync with config (merchant may have customised it)
        var labelEl = btn.querySelector('.zcc-btn-label');
        if (labelEl) labelEl.textContent = cfg.buttonText;
      }
    }

    function checkZip() {
      var zip = normalizeZip(inp.value);
      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
      if (!zip) { inp.focus(); return; }

      setBtnLoading(true);
      res.innerHTML = "";

      fetch(
        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
          "&zip=" + encodeURIComponent(zip)
      )
        .then(function (r) {
          if (!r.ok) {
            // Non-2xx: try to parse JSON error body, fall back to status text
            return r.json().catch(function() {
              return { error: 'Server error (' + r.status + ')' };
            });
          }
          return r.json();
        })
        .then(function (data) {
          setBtnLoading(false);

          // If the API returned an error object (no allowed field), treat as a
          // transient server error and show it in the result area rather than
          // falling through with undefined message text.
          if (data.error && data.allowed === undefined) {
            console.error('[Pinzo] API returned error:', data.error, '| API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"');
            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
            try {
              sessionStorage.removeItem('zcc:valid');
              sessionStorage.removeItem('zcc:zip');
              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
            } catch(e) {}
            return;
          }

          // Store validation result for cart page
          try {
            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
            sessionStorage.setItem('zcc:zip', zip);
            sessionStorage.setItem('zcc:shop', SHOP);
            // Fire custom event for other scripts to listen to
            window.dispatchEvent(new CustomEvent('zcc:validated', {
              detail: { valid: data.allowed, zip: zip }
            }));
          } catch(e) { /* sessionStorage may be unavailable */ }

          if (data.allowed) {
            var html = '<div class="zcc-result ok">' +
              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
              '<div class="zcc-result-content">' +
              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
            if (cfg.showEta && data.eta) {
              html += '<div class="zcc-meta">' + ICONS.truck + '<span>Estimated delivery: <strong>' + esc(data.eta) + '</strong></span></div>';
            }
            // Delivery Date
            if (cfg.showDeliveryDate && data.estimatedDeliveryDate) {
              var dateStr = formatDeliveryDate(data.estimatedDeliveryDate);
              if (dateStr) {
                html += '<div class="zcc-meta zcc-delivery-date">' + ICONS.calendar + '<span>Expected by <strong>' + esc(dateStr) + '</strong></span></div>';
              }
            }
            if (cfg.showZone && data.zone) {
              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
            }
            if (cfg.showDeliveryDays && data.daysOfWeek) {
              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
            }
            if (cfg.showCutoffTime && data.cutoffTime) {
              var parts = data.cutoffTime.split(':');
              var hr = parseInt(parts[0], 10);
              var min = parts[1] || '00';
              var ampm = hr >= 12 ? 'PM' : 'AM';
              var hr12 = hr % 12 || 12;
              html += '<div class="zcc-meta zcc-cutoff">' + ICONS.clock + '<span>Order by <strong>' + hr12 + ':' + min + ' ' + ampm + '</strong> for same-day</span></div>';
            }
            // Countdown Timer
            if (cfg.showCountdown && data.cutoffTime) {
              html += buildCountdownHtml(data.cutoffTime, wid);
            }
            if (cfg.showCod !== false) {
              if (data.codAvailable === true) {
                html += '<div class="zcc-cod zcc-cod--available">' + ICONS.card + ' Cash on Delivery Available</div>';
              } else if (data.codAvailable === false) {
                html += '<div class="zcc-cod zcc-cod--unavailable">' + ICONS.card + ' COD Not Available</div>';
              }
            }
            if (cfg.showReturnPolicy !== false && data.returnPolicy) {
              html += '<div class="zcc-return-policy">' + ICONS.refresh + '<span>' + esc(data.returnPolicy) + '</span></div>';
            }
            // Delivery Fee
            if (cfg.showDeliveryFee !== false) {
              if (data.deliveryFee === 0 || data.deliveryFee === null) {
                html += '<div class="zcc-delivery-fee zcc-delivery-fee--free">' + ICONS.truck + ' Free Delivery</div>';
              } else if (data.deliveryFee != null && data.deliveryFee > 0) {
                html += '<div class="zcc-delivery-fee zcc-delivery-fee--paid">' + ICONS.truck + ' Delivery: $' + data.deliveryFee.toFixed(2) + '</div>';
              }
              if (data.freeShippingAbove != null && data.freeShippingAbove > 0 && (data.deliveryFee == null || data.deliveryFee > 0)) {
                html += '<div class="zcc-meta" style="margin-top:3px !important"><span style="font-size:11px !important;color:#6d7175 !important">Free delivery on orders over $' + data.freeShippingAbove.toFixed(2) + '</span></div>';
              }
            }
            html += '</div></div>';
            res.innerHTML = html;
            if (cfg.showCountdown && data.cutoffTime) {
              startCountdownUpdater(wid, data.cutoffTime);
            }
          } else {
            var html = '<div class="zcc-result fail">' +
              '<div class="zcc-result-icon">' + ICONS.xCircle + '</div>' +
              '<div class="zcc-result-content">' +
              '<div class="zcc-result-message">' + esc(data.message) + '</div>' +
              '</div></div>';
            if (cfg.showWaitlistOnFailure) {
              html +=
                '<div class="zcc-wl">' +
                '<div id="' + wid + '-wl-form">' +
                '<div class="zcc-wl-title">' + ICONS.mail + ' Get notified when we deliver to your area</div>' +
                '<input class="zcc-wl-input" type="text" id="' + wid + '-wl-name" placeholder="Your name (optional)" aria-label="Your name" />' +
                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Your email address" aria-label="Your email address" required />' +
                '<input class="zcc-wl-input" type="text" id="' + wid + '-wl-zip" placeholder="ZIP code" aria-label="ZIP code" value="' + escAttr(zip) + '" required />' +
                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button"><span class="zcc-wl-btn-icon">' + ICONS.mail + '</span><span class="zcc-wl-btn-label">Notify Me</span></button>' +
                '</div>' +
                '</div>';
            }
            res.innerHTML = html;

            if (cfg.showWaitlistOnFailure) {
              // Social proof count
              if (cfg.showSocialProof && data.waitlistCount && data.waitlistCount > 0) {
                var wlSection = document.getElementById(wid + "-wl-name");
                if (wlSection && wlSection.parentNode) {
                  var spEl = document.createElement('div');
                  spEl.className = 'zcc-social-proof';
                  var count = data.waitlistCount;
                  var spIcon = document.createElement('span');
                  spIcon.className = 'zcc-social-proof-icon';
                  spIcon.innerHTML = ICONS.users;
                  var spText = document.createTextNode(' Join ' + count + ' other' + (count !== 1 ? 's' : '') + ' waiting for delivery to your area');
                  spEl.appendChild(spIcon);
                  spEl.appendChild(spText);
                  wlSection.parentNode.insertBefore(spEl, wlSection);
                }
              }

              var wBtn = document.getElementById(wid + "-wl-btn");
              if (wBtn) {
                wBtn.addEventListener("click", function () {
                  var nameEl = document.getElementById(wid + "-wl-name");
                  var emailEl = document.getElementById(wid + "-wl-email");
                  var zipEl = document.getElementById(wid + "-wl-zip");
                  var name = nameEl ? nameEl.value.trim() : "";
                  var email = emailEl ? emailEl.value.trim() : "";
                  var wlZip = zipEl ? normalizeZip(zipEl.value) : zip;
                  if (!email) { if (emailEl) emailEl.focus(); return; }
                  if (!wlZip) { if (zipEl) zipEl.focus(); return; }
                  joinWaitlist(wlZip, email, name, wBtn);
                });
              }
            }
          }

          // Block/unblock Add to Cart based on result (if merchant enabled this)
          if (cfg.blockCartOnInvalid) {
            var ATC_SELECTORS = [
              'button[name="add"]',
              '.product-form__submit',
              '[data-product-add]',
              '.btn--add-to-cart',
              '.product-form button[type="submit"]',
              'button.shopify-payment-button__button',
              '.shopify-payment-button button',
              'button.product-form__cart-submit'
            ].join(',');

            try {
              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
              atcBtns.forEach(function(b) {
                if (!b.closest('#zcc-widget, [data-zcc-widget]')) { // Don't touch our own widget's button
                  if (data.allowed) {
                    b.disabled = false;
                    b.style.opacity = '';
                    b.title = b.getAttribute('data-zcc-orig-title') || '';
                    b.removeAttribute('data-zcc-orig-title');
                    b.removeAttribute('data-zcc-blocked');
                  } else {
                    b.setAttribute('data-zcc-orig-title', b.title || '');
                    b.disabled = true;
                    b.style.opacity = '0.5';
                    b.title = 'Please enter a valid ZIP code to continue';
                    b.setAttribute('data-zcc-blocked', 'true');
                  }
                }
              });
            } catch(e) { /* DOM query may fail in some contexts */ }
          }
        })
        .catch(function (err) {
          setBtnLoading(false);
          // Log to console so merchants/developers can diagnose API connectivity issues.
          // The URL is logged so we can immediately see if the proxy/API base is wrong.
          console.error('[Pinzo] ZIP check failed. API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"', err);
          res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
          try {
            sessionStorage.removeItem('zcc:valid');
            sessionStorage.removeItem('zcc:zip');
            window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
          } catch(e) {}
        });
    }

    btn.addEventListener("click", checkZip);
    inp.addEventListener("keydown", function (e) {
      if (e.key === "Enter") checkZip();
    });

    // When the customer edits the ZIP input after a successful check, re-block
    // cart buttons until they verify the new ZIP. Cart buttons must ONLY be
    // re-enabled by a successful API response (data.allowed === true).
    // Note: we track whether the last verification was successful so we only
    // re-block when the value actually changes away from the verified ZIP.
    if (cfg.blockCartOnInvalid) {
      inp.addEventListener('input', function() {
        try {
          var lastValidZip = sessionStorage.getItem('zcc:zip');
          var lastValid = sessionStorage.getItem('zcc:valid') === 'true';
          // If the last check was successful, re-block as soon as the input
          // changes (any change away from the verified value is unverified).
          if (lastValid && lastValidZip) {
            var currentVal = normalizeZip(inp.value);
            if (currentVal !== lastValidZip) {
              // Mark as unverified immediately
              sessionStorage.setItem('zcc:valid', 'false');
              sessionStorage.removeItem('zcc:zip');
              // Re-block ATC buttons until the new ZIP is verified
              var ATC_SELECTORS = [
                'button[name="add"]',
                '.product-form__submit',
                '[data-product-add]',
                '.btn--add-to-cart',
                '.product-form button[type="submit"]',
                'button.shopify-payment-button__button',
                '.shopify-payment-button button',
                'button.product-form__cart-submit'
              ].join(',');
              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
              atcBtns.forEach(function(b) {
                if (!b.closest('[data-zcc-widget]')) {
                  if (!b.getAttribute('data-zcc-blocked')) {
                    b.setAttribute('data-zcc-orig-title', b.title || '');
                  }
                  b.disabled = true;
                  b.style.opacity = '0.5';
                  b.title = 'Please check ZIP code availability first';
                  b.setAttribute('data-zcc-blocked', 'true');
                }
              });
            }
          }
          // If the last check was NOT successful (buttons are already blocked),
          // do nothing — clearing or changing the input must never unblock buttons.
        } catch(e) {}
      });
    }
  }

  function joinWaitlist(zip, email, name, wBtn) {
    // Store original button HTML so we can restore it exactly (same pattern as setBtnLoading)
    var wBtnOriginalHtml = wBtn.innerHTML;

    wBtn.disabled = true;
    wBtn.classList.add('zcc-btn--loading');
    wBtn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';

    var payload = { shop: SHOP, zip: zip, email: email };
    if (name) payload.name = name;

    function restoreBtn() {
      wBtn.disabled = false;
      wBtn.classList.remove('zcc-btn--loading');
      wBtn.innerHTML = wBtnOriginalHtml;
    }

    fetch(API_BASE + "/api/waitlist", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then(function (r) { return r.json(); })
      .then(function (data) {
        var wlEl = wBtn.closest(".zcc-wl");
        if (data.success) {
          if (wlEl) wlEl.innerHTML =
            '<div class="zcc-wl-success">' +
            '<span class="zcc-wl-success-icon">' + ICONS.check + '</span>' +
            '<span>Your request has been submitted! We\u2019ll notify you when delivery is available.</span>' +
            '</div>';
        } else {
          restoreBtn();
        }
      })
      .catch(function () {
        restoreBtn();
      });
  }

  // ── Inline position ─────────────────────────────────────────────────────────
  function renderInline(cfg, WID, rad) {
    injectCss(WID, cfg, rad);
    container.id = WID;
    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
    wireWidget(WID, cfg, API_BASE, SHOP);
  }

  // ── Floating position ────────────────────────────────────────────────────────
  function renderFloating(cfg, WID, rad) {
    // The original container becomes invisible (just an anchor)
    container.style.display = "none";

    injectCss(WID, cfg, rad);

    // Additional styles for floating UI
    var floatCss =
      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:12px !important}" +
      "#" + WID + "-panel{" +
        "background:" + cfg.backgroundColor + " !important;border-radius:16px !important;" +
        "box-shadow:0 12px 40px rgba(0,0,0,.15),0 4px 12px rgba(0,0,0,.08) !important;overflow:hidden !important;" +
        "animation:zcc-slide-in 0.25s ease !important;max-width:380px !important;width:380px !important" +
      "}" +
      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
      "#" + WID + "-panel .zcc-panel-header{" +
        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
        "padding:16px 20px 0 !important;margin-bottom:0 !important" +
      "}" +
      "#" + WID + "-panel .zcc-panel-title{font-size:14px !important;font-weight:700 !important;color:" + cfg.textColor + " !important;display:flex !important;align-items:center !important;gap:8px !important}" +
      "#" + WID + "-panel .zcc-panel-close{" +
        "background:none !important;border:none !important;cursor:pointer !important;line-height:1 !important;" +
        "color:" + cfg.textColor + " !important;opacity:.5 !important;padding:4px !important;border-radius:6px !important;transition:all 0.15s !important" +
      "}" +
      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important;background:#f6f6f7 !important}" +
      "#" + WID + "-trigger{" +
        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
        "border-radius:50px !important;padding:14px 22px !important;font-size:14px !important;font-weight:600 !important;" +
        "cursor:pointer !important;box-shadow:0 4px 16px " + cfg.primaryColor + "40 !important;white-space:nowrap !important;" +
        "transition:all 0.2s ease !important;display:flex !important;align-items:center !important;gap:8px !important;animation:zcc-pulse 2s infinite !important" +
      "}" +
      "#" + WID + "-trigger:hover{transform:scale(1.03) !important;box-shadow:0 6px 20px " + cfg.primaryColor + "50 !important}" +
      "@media(max-width:420px){#" + WID + "-panel{width:calc(100vw - 32px) !important;max-width:none !important}#" + WID + "-float{left:16px !important;right:16px !important;align-items:stretch !important}}";

    var floatStyle = document.createElement("style");
    floatStyle.textContent = floatCss;
    document.head.appendChild(floatStyle);

    // Build floating shell
    var floatEl = document.createElement("div");
    floatEl.id = WID + "-float";
    floatEl.innerHTML =
      '<div id="' + WID + '-panel" class="zcc-hidden">' +
        '<div class="zcc-panel-header">' +
          '<span class="zcc-panel-title">' +
            '<svg viewBox="0 0 24 24" fill="none" stroke="' + escAttr(cfg.primaryColor) + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
            ' Delivery Check</span>' +
          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">' +
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M18 6L6 18"/><path d="M6 6l12 12"/></svg>' +
          '</button>' +
        '</div>' +
        '<div id="' + WID + '" data-zcc-widget="true" style="border:none !important;box-shadow:none !important;max-width:none !important;padding:16px 20px 20px !important">' +
          buildWidgetInner(WID, cfg, cfg.buttonText, false) +
        '</div>' +
      '</div>' +
      '<button id="' + WID + '-trigger" type="button">' +
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
        esc(cfg.buttonText || "Check Delivery") +
      '</button>';

    document.body.appendChild(floatEl);

    // Wire toggle
    var trigger = document.getElementById(WID + "-trigger");
    var panel = document.getElementById(WID + "-panel");
    var closeBtn = document.getElementById(WID + "-close");

    if (trigger && panel) {
      trigger.addEventListener("click", function () {
        panel.classList.toggle("zcc-hidden");
      });
    }
    if (closeBtn && panel) {
      closeBtn.addEventListener("click", function () {
        panel.classList.add("zcc-hidden");
      });
    }
    // Close on outside click
    document.addEventListener("click", function (e) {
      if (!floatEl.contains(e.target)) {
        if (panel) panel.classList.add("zcc-hidden");
      }
    });

    wireWidget(WID, cfg, API_BASE, SHOP);
  }

  // ── Popup position ───────────────────────────────────────────────────────────
  function renderPopup(cfg, WID, rad) {
    injectCss(WID, cfg, rad);

    var popupCss =
      "#" + WID + "-overlay{" +
        "display:none !important;position:fixed !important;inset:0 !important;" +
        "background:rgba(0,0,0,.5) !important;backdrop-filter:blur(4px) !important;-webkit-backdrop-filter:blur(4px) !important;" +
        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
      "}" +
      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
      "#" + WID + "-modal{" +
        "background:" + cfg.backgroundColor + " !important;border-radius:16px !important;overflow:hidden !important;" +
        "max-width:480px !important;width:100% !important;position:relative !important;" +
        "box-shadow:0 24px 48px rgba(0,0,0,.2) !important;animation:zcc-slide-in 0.3s ease !important" +
      "}" +
      "#" + WID + "-modal .zcc-modal-header{" +
        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
        "padding:20px 24px 0 !important" +
      "}" +
      "#" + WID + "-modal .zcc-modal-title{font-size:15px !important;font-weight:700 !important;color:" + cfg.textColor + " !important;display:flex !important;align-items:center !important;gap:8px !important}" +
      "#" + WID + "-modal .zcc-modal-close{" +
        "background:none !important;border:none !important;" +
        "cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5 !important;" +
        "padding:4px !important;border-radius:6px !important;transition:all 0.15s !important;line-height:1 !important" +
      "}" +
      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important;background:#f6f6f7 !important}" +
      "#" + WID + "-popup-trigger{" +
        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
        "border-radius:" + rad + " !important;padding:12px 28px !important;font-size:14px !important;font-weight:600 !important;" +
        "cursor:pointer !important;transition:all 0.2s ease !important;display:inline-flex !important;align-items:center !important;gap:8px !important" +
      "}" +
      "#" + WID + "-popup-trigger:hover{filter:brightness(1.08) !important;transform:translateY(-1px) !important;box-shadow:0 4px 12px " + cfg.primaryColor + "30 !important}";

    var popupStyle = document.createElement("style");
    popupStyle.textContent = popupCss;
    document.head.appendChild(popupStyle);

    // Trigger button renders in-place (inside the block)
    // Uses cfg.buttonText (e.g. "Check") — NOT cfg.heading to avoid a third copy of the heading text
    container.innerHTML =
      '<button id="' + WID + '-popup-trigger" type="button">' +
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
        esc(cfg.buttonText || cfg.heading) +
      '</button>';

    // Overlay + modal append to body
    var overlay = document.createElement("div");
    overlay.id = WID + "-overlay";
    overlay.innerHTML =
      '<div id="' + WID + '-modal">' +
        '<div class="zcc-modal-header">' +
          '<span class="zcc-modal-title">' +
            '<svg viewBox="0 0 24 24" fill="none" stroke="' + escAttr(cfg.primaryColor) + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
            ' ' + esc(cfg.heading) + '</span>' +
          '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">' +
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M18 6L6 18"/><path d="M6 6l12 12"/></svg>' +
          '</button>' +
        '</div>' +
        '<div id="' + WID + '" data-zcc-widget="true" style="border:none !important;box-shadow:none !important;max-width:none !important;padding:16px 24px 24px !important">' +
          buildWidgetInner(WID, cfg, cfg.buttonText, false) +
        '</div>' +
      '</div>';
    document.body.appendChild(overlay);

    var trigger = document.getElementById(WID + "-popup-trigger");
    var closeBtn = document.getElementById(WID + "-modal-close");
    var modal = document.getElementById(WID + "-modal");

    function openPopup() { overlay.classList.add("zcc-open"); }
    function closePopup() { overlay.classList.remove("zcc-open"); }

    if (trigger) trigger.addEventListener("click", openPopup);
    if (closeBtn) closeBtn.addEventListener("click", closePopup);

    // Close on overlay backdrop click (not modal content)
    overlay.addEventListener("click", function (e) {
      if (e.target === overlay) closePopup();
    });

    // Close on Escape key
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") closePopup();
    });

    wireWidget(WID, cfg, API_BASE, SHOP);
  }

  function esc(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function escAttr(str) {
    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
  }
  } // end init()
})();
</script>

{% endif %}

