<div
  id="zcc-widget-{{ block.id }}"
  data-zcc-widget="true"
  data-shop="{{ shop.permanent_domain }}"
  data-api="{{ app.url }}"
  data-proxy="/apps/zipcheck"
  data-block="{{ block.id }}"
  {{ block.shopify_attributes }}
></div>

<script>
(function () {
  // Wait for app embed to set window.__zccAppEnabled.
  // App embed (target: body) may load after this section block, so we poll briefly.
  var maxWait = 3000; // ms
  var interval = 50;  // ms
  var elapsed = 0;

  function tryInit() {
    if (window.__zccAppEnabled) {
      init();
    } else if (elapsed < maxWait) {
      elapsed += interval;
      setTimeout(tryInit, interval);
    }
    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
  }

  // Start checking — if already set, runs immediately
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', tryInit);
  } else {
    tryInit();
  }

  function init() {
  var ROOT_ID = "zcc-widget-{{ block.id }}";
  var container = document.getElementById(ROOT_ID);
  if (!container) return;

  var SHOP = container.dataset.shop;
  // app.url resolves to the App Proxy URL (e.g. https://store.myshopify.com/apps/zipcheck).
  // If for any reason it is empty (e.g. dev environment or Shopify Liquid context issue),
  // fall back to the relative proxy path so the request still routes correctly through
  // Shopify's App Proxy rather than hitting the store's own domain as a missing route.
  var _rawApi = (container.dataset.api || "").replace(/\/$/, "");
  var _proxyPath = (container.dataset.proxy || "/apps/zipcheck").replace(/\/$/, "");
  // Prefer app.url when it looks like a full URL; otherwise use the relative proxy path
  // (which Shopify will forward to our app via the App Proxy config).
  var API_BASE = (_rawApi && _rawApi.indexOf("http") === 0) ? _rawApi : _proxyPath;

  // ── Pre-lock: applied synchronously BEFORE the async config fetch ────────────
  // This eliminates the race window where ATC/Buy Now buttons are clickable
  // while the config fetch is in flight (typically 100–500 ms).
  // renderWidget() will call _zccUnlock() immediately if the feature is
  // disabled (lockButtonsUntilZipCheck:false) or position is "inline".
  var _zccLockStyleId = 'zcc-lock-style';
  function _zccInjectLockCss() {
    if (document.getElementById(_zccLockStyleId)) return;
    var s = document.createElement('style');
    s.id = _zccLockStyleId;
    s.textContent =
      'html[data-zcc-locked] form[action*="/cart/add"] button[type="submit"],' +
      'html[data-zcc-locked] button[name="add"],' +
      'html[data-zcc-locked] .product-form__submit,' +
      'html[data-zcc-locked] [data-product-add],' +
      'html[data-zcc-locked] .btn--add-to-cart,' +
      'html[data-zcc-locked] .product-form button[type="submit"],' +
      'html[data-zcc-locked] button.product-form__cart-submit,' +
      'html[data-zcc-locked] .product__submit button[type="submit"],' +
      'html[data-zcc-locked] .pdp-form button[type="submit"]' +
      '{opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
      'html[data-zcc-locked] .shopify-payment-button,' +
      'html[data-zcc-locked] [data-shopify="payment-button"],' +
      'html[data-zcc-locked] .shopify-payment-button__button--unbranded' +
      '{position:relative!important;opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
      'html[data-zcc-locked] .shopify-payment-button::after,' +
      'html[data-zcc-locked] [data-shopify="payment-button"]::after' +
      '{content:""!important;position:absolute!important;inset:0!important;z-index:2147483647!important;cursor:not-allowed!important;background:transparent!important;}';
    (document.head || document.documentElement).appendChild(s);
  }
  function _zccLock() {
    _zccInjectLockCss();
    document.documentElement.setAttribute('data-zcc-locked', '1');
  }
  function _zccUnlock() {
    document.documentElement.removeAttribute('data-zcc-locked');
  }
  // Lock immediately — but skip if the customer already validated this shop's
  // ZIP in this session (avoids flash-of-disabled-buttons on page refresh).
  var _priorValid = false;
  try {
    _priorValid = sessionStorage.getItem('zcc:valid') === 'true' &&
                  sessionStorage.getItem('zcc:shop') === SHOP;
  } catch(e) {}
  if (!_priorValid) {
    _zccLock();
  }

  // Always fetch fresh config from the API so color/setting changes made in the
  // admin are reflected on the storefront immediately. The metafield-embedded
  // data-config attribute is intentionally ignored here: it is baked into
  // Shopify's CDN-cached HTML at render time and can be stale for many minutes
  // after a merchant saves new settings. The API endpoint returns
  // Cache-Control: no-store so it is always up to date.

