              background: cfg.backgroundColor,
              borderRadius: 14,
              boxShadow: "0 8px 32px rgba(0,0,0,.12), 0 2px 8px rgba(0,0,0,.06)",
              width: "100%",
              overflow: "hidden",
              border: "1px solid rgba(0,0,0,0.06)",
            }}
          >
            {/* Panel header */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "12px 14px",
                background: `linear-gradient(135deg, ${cfg.primaryColor}08, ${cfg.primaryColor}03)`,
                borderBottom: "1px solid rgba(0,0,0,0.06)",
              }}
            >
              <div
                style={{
                  fontSize: 13,
                  fontWeight: 700,
                  color: cfg.textColor,
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                }}
              >
                <span style={{
                  display: "inline-flex",
                  alignItems: "center",
                  justifyContent: "center",
                  width: 26,
                  height: 26,
                  borderRadius: "50%",
                  background: cfg.primaryColor + "18",
                }}>
                  {pinIcon}
                </span>
                {cfg.heading}
              </div>
              <button
                type="button"
                onClick={() => setPanelOpen(false)}
                style={{
                  background: "rgba(0,0,0,0.05)",
                  border: "none",
                  cursor: "pointer",
                  color: cfg.textColor,
                  borderRadius: 6,
                  width: 24,
                  height: 24,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: 0,
                }}
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ width: 14, height: 14 }}>
                  <path d="M18 6L6 18" /><path d="M6 6l12 12" />
                </svg>
              </button>
            </div>
            {/* Panel body */}
            <div style={{ padding: "12px 14px 14px" }}>
              <style dangerouslySetInnerHTML={{ __html: `#${wid} .zcc-heading{display:none}` }} />
              {widgetHtml}
            </div>
          </div>
        )}

        {/* Trigger button */}
        <button
          type="button"
          onClick={() => setPanelOpen(!panelOpen)}
          style={{
            background: cfg.primaryColor,
            color: "#fff",
            border: "none",
            borderRadius: 50,
            padding: "12px 20px",
            fontSize: 13,
            fontWeight: 600,
            display: "inline-flex",
            alignItems: "center",
            gap: 7,
            cursor: "pointer",
            boxShadow: `0 4px 12px ${cfg.primaryColor}30`,
            whiteSpace: "nowrap" as const,
          }}
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ width: 16, height: 16 }}>
            <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z" /><circle cx="12" cy="10" r="3" />
          </svg>
          {cfg.buttonText || "Check Delivery"}
        </button>
      </div>
    </>
  );
}

